<?php
// Exports read saved batch allocations; they never calculate or post new allocations.
function ia_export_build($id){
 if(!access_page_allowed('inflow'))throw new Exception('Inflow history access required.');
 $q=db()->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([(int)$id]);$b=$q->fetch();if(!$b)throw new Exception('Inflow batch not found.');$meta=json_decode($b['result_json']??'[]',true)?:[];$a=prc_allocation($b);if(!$a||empty($a['lines'])||!is_array($a['lines']))throw new Exception('No saved incoming allocation is available for this batch.');
 $legacy=(int)array_sum(array_column($a['lines'],'Warehouse'))!==0;$keys=array_merge(['incoming','Shopee','Lazada','TikTok','Website'],$legacy?['Warehouse']:[],['Non-Sellable']);$headers=array_merge(['Product / SKU','Incoming','Shopee','Lazada','TikTok','Website'],$legacy?['Legacy Warehouse']:[],['Non-Sellable']);$rows=[];$totals=array_fill(0,count($keys),0);$p=db()->prepare('SELECT master_sku,name FROM products WHERE id=?');
 foreach($a['lines'] as $pid=>$line){$p->execute([(int)$pid]);$product=$p->fetch();$row=[$product?$product['master_sku'].' · '.$product['name']:($line['product']??'Archived product')];foreach($keys as $i=>$key){$n=(int)($line[$key]??0);$row[]=$n;$totals[$i]+=$n;}$rows[]=$row;}
 $state=match($b['status']){'Confirmed'=>'Posted allocation','Reversed'=>'Original allocation — batch reversed','Cancelled'=>'Saved allocation — batch cancelled',default=>'Saved review — not posted'};
 return ['title'=>'Incoming Stock Allocation','headers'=>$headers,'rows'=>$rows,'total'=>array_merge(['TOTAL'],$totals),'meta'=>['Batch'=>$b['batch_ref'],'Reference'=>$b['reference_no']??'','Received Date'=>$b['txn_date'],'Supplier / Source'=>$b['source_name']??'','Batch Status'=>$b['status'],'Allocation State'=>$state,'Reviewed By'=>$a['saved_name']??'','Reviewed At'=>$a['saved_at']??'','Posted At'=>$a['confirmed_at']??'','Description Basis'=>'Current Product Master; saved allocation plus approved item corrections','Exported At'=>date('Y-m-d H:i:s')]];
}
function ia_export_toolbar($b){if(!access_page_allowed('inflow'))return;$url='index.php?page=inflow&amp;id='.(int)$b['id'].'&amp;allocation_export=';echo '<div class="om-actions" aria-label="Incoming allocation downloads"><a class="btn secondary sm" href="'.$url.'xlsx">Download Excel</a><a class="btn secondary sm" href="'.$url.'pdf">Download PDF</a><a class="btn ghost sm" href="'.$url.'print" target="_blank" rel="noopener">Print</a></div>';}
function ia_export_html($r,$print=false){
 $h='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Incoming Stock Allocation</title><style>@page{size:A4 landscape;margin:12mm 10mm 16mm}body{font-family:"DejaVu Sans",Arial,sans-serif;font-size:10px;color:#172b46}h1{font-size:20px;margin:0 0 4px}.meta{margin:14px 0;line-height:1.5}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{padding:8px 5px;border-bottom:1px solid #dce4ed;vertical-align:top;word-wrap:break-word;text-align:right}th{background:#edf2f7}th:first-child,td:first-child{text-align:left;width:37%}tr{page-break-inside:avoid}.total{font-weight:bold;background:#f3f6f9}.actions{margin-bottom:14px}.actions button{padding:8px 16px}@media print{.actions{display:none}}</style></head><body>'.($print?'<div class="actions"><button onclick="window.print()">Print</button></div>':'').'<h1>'.e($r['title']).'</h1><div>E-commerce Inventory Management System</div><div class="meta">';foreach($r['meta'] as $k=>$v)if((string)$v!=='')$h.='<div><b>'.e($k).':</b> '.e($v).'</div>';$h.='</div><table><colgroup><col style="width:37%">';for($i=1;$i<count($r['headers']);$i++)$h.='<col style="width:'.(63/(count($r['headers'])-1)).'%">';$h.='</colgroup><thead><tr>';foreach($r['headers'] as $v)$h.='<th>'.e($v).'</th>';$h.='</tr></thead><tbody>';foreach(array_merge($r['rows'],[$r['total']]) as $i=>$row){$h.='<tr'.($i===count($r['rows'])?' class="total"':'').'>';foreach($row as $j=>$v)$h.='<td>'.e($j?number_format($v):$v).'</td>';$h.='</tr>';}
 return $h.'</tbody></table>'.($print?'<script>window.addEventListener("load",()=>window.print());</script>':'').'</body></html>';
}
function ia_write_pdf($path,$r){
 $loader=__DIR__.'/third_party/report_pdf/vendor/autoload.php';if(!is_file($loader))throw new Exception('Upload the complete third_party/report_pdf folder for PDF downloads.');require_once $loader;$o=new \Dompdf\Options();$o->set('isRemoteEnabled',false);$o->set('isPhpEnabled',false);$o->set('isJavascriptEnabled',false);$o->set('defaultFont','DejaVu Sans');$o->set('tempDir',sys_get_temp_dir());$o->set('fontCache',sys_get_temp_dir());$o->setChroot(__DIR__.'/third_party/report_pdf/vendor/dompdf/dompdf');$pdf=new \Dompdf\Dompdf($o);$pdf->setPaper('A4','landscape');$pdf->loadHtml(ia_export_html($r),'UTF-8');$pdf->render();$font=$pdf->getFontMetrics()->getFont('DejaVu Sans','normal');$pdf->getCanvas()->page_text(720,570,'Page {PAGE_NUM} of {PAGE_COUNT}',$font,8,[.25,.3,.4]);if(file_put_contents($path,$pdf->output())===false)throw new Exception('Cannot prepare allocation PDF.');
}
function ia_download($id,$format){$path=null;try{if(!in_array($format,['xlsx','pdf','print'],true))throw new Exception('Choose Excel, PDF or Print.');$r=ia_export_build($id);header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');if($format==='print'){header('Content-Type: text/html; charset=utf-8');echo ia_export_html($r,true);return;}$path=tempnam(sys_get_temp_dir(),'incoming-allocation-');if($path===false)throw new Exception('Cannot prepare allocation download.');if($format==='xlsx')report_write_xlsx($path,$r['title'],$r['headers'],array_merge($r['rows'],[$r['total']]),$r['meta']);else ia_write_pdf($path,$r);header('Content-Type: '.($format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'application/pdf'));header('Content-Disposition: attachment; filename="Incoming_Allocation_'.(int)$id.'.'.$format.'"');readfile($path);}catch(Throwable $e){http_response_code(400);header('Content-Type: text/html; charset=utf-8');echo '<h1>Allocation export unavailable</h1><p>'.e(safe_error_message($e)).'</p><a href="index.php?page=inflow">Back to Inflow</a>';}finally{if($path&&is_file($path))unlink($path);}}

